33		result, err := r.renderCondition(cond)
34		if err != nil {
35			return Statement{}, err
36		}
37		args := r.args
38		if args == nil {
39			args = []any{}
40		}
41	
42		switch {
43		case result.unsatisfiable:
44			return Statement{
45				SQL:  "1 = 0",
46				Args: args,
47			}, nil
48		case result.trivial:
49			return Statement{
50				SQL:  "",
51				Args: args,
52			}, nil
